            if len(cols) >= 3 or r in (top, bottom):
                for c in range(left, right + 1):
                    if grid[r][c] == bg:
                        out[r][c] = 2
        for c in (left, right):
            for r in range(top, bottom + 1):
                if grid[r][c] == bg:
